const assert = require('node:assert/strict');
const { chromium } = require('playwright-core');

(async () => {
  const [base, baseCookie, billingCookie, readerCookie, id, location, asset, field, tag] = process.argv.slice(2);
  const browser = await chromium.launch({executablePath: process.env.BROWSER_EXECUTABLE, headless: true, args: ['--no-sandbox']});
  try {
    const open = async cookie => {
      const context = await browser.newContext({viewport: {width: 390, height: 844}});
      await context.addCookies([{name:'session', value:cookie, url:base, httpOnly:true}]);
      return context.newPage();
    };
    const page = await open(baseCookie);
    const path = `${base}/leases/${id}`;
    assert.equal((await page.goto(path)).status(),200);
    await page.locator('[name=title]').fill('Browser external agreement');
    await page.locator('[name=reference]').fill('Nonunique reference');
    await page.locator('[name=execution_date]').fill('2026-02-01');
    await page.locator('[name=starts_on]').fill('2030-12-31');
    await page.locator('[name=ends_on]').fill('2030-01-01');
    await page.locator('[name=premises_id]').selectOption(location);
    await page.locator('[name=asset_ids]').selectOption(asset);
    await page.locator(`[name=custom_field_${field}]`).fill('First line\nSecond line');
    let response = page.waitForResponse(r => r.request().method()==='POST' && r.url()===path);
    await page.getByRole('button',{name:'Save Draft details',exact:true}).click();
    assert.ok([200,303].includes((await response).status()));
    await page.waitForFunction(() => document.querySelector('[name=revision]')?.value === '1');
    await page.reload();
    assert.equal(await page.locator('[name=title]').inputValue(),'Browser external agreement');
    assert.equal(await page.locator('[name=ends_on]').inputValue(),'2030-01-01');
    assert.equal(await page.locator(`[name=custom_field_${field}]`).inputValue(),'First line\nSecond line');
    await page.locator('textarea[name=content]').first().fill('Browser Lease comment');
    const commentForm = page.locator('form').filter({has:page.locator('textarea[name=content]')}).first();
    response = page.waitForResponse(r=>r.request().method()==='POST' && r.url()===path+'/comments');
    await commentForm.locator('button[type=submit]').click();
    assert.equal((await response).status(),200);
    await page.getByText('Browser Lease comment',{exact:true}).waitFor();
    // Use the shared tag widget's actual attach control.
    response = page.waitForResponse(r=>r.request().method()==='POST' && r.url().endsWith(`/tags/${tag}/attach`));
    await page.locator('#tag-widget .tag-select').selectOption(tag);
    assert.equal((await response).status(),200);
    await page.locator('input[type=file]').setInputFiles({name:'browser-agreement.txt',mimeType:'text/plain',buffer:Buffer.from('External browser agreement')});
    response = page.waitForResponse(r=>r.request().method()==='POST' && r.url().includes('/files?'));
    await page.getByRole('button',{name:'Upload files',exact:true}).click();
    assert.equal((await response).status(),200);
    await page.locator('[name=agreement_file_id] option').filter({hasText:'browser-agreement.txt'}).waitFor({state:'attached'});
    await page.waitForLoadState('load');
    await page.reload();
    await page.locator('[name=agreement_file_id]').selectOption({label:'browser-agreement.txt'});
    response=page.waitForResponse(r=>r.request().method()==='POST' && r.url()===path);
    await page.getByRole('button',{name:'Save Draft details',exact:true}).click();
    assert.ok([200,303].includes((await response).status()));
    await page.waitForFunction(() => document.querySelector('[name=revision]')?.value === '2');
    await page.reload();
    assert.notEqual(await page.locator('[name=agreement_file_id]').inputValue(),'');
    assert.equal((await page.goto(path+'/billing')).status(),404);
    const finance=await open(billingCookie);
    assert.equal((await finance.goto(path+'/billing')).status(),200);
    await finance.locator('[name=initial_cents]').fill('1234567');
    await finance.locator('[name=rent_cents]').fill('7654321');
    await finance.locator('[name=tax_rate]').fill('12.3456');
    response=finance.waitForResponse(r=>r.request().method()==='POST' && r.url()===path+'/billing');
    await finance.getByRole('button',{name:'Save Billing terms',exact:true}).click();
    assert.ok([200,303].includes((await response).status()));
    await finance.waitForFunction(() => document.querySelector('[name=revision]')?.value === '1');
    await finance.reload();
    assert.equal(await finance.locator('[name=rent_cents]').inputValue(),'7654321');
    assert.doesNotMatch(await finance.content(),/Browser external agreement|Browser Lease comment|browser-agreement\.txt|custom_field_/);
    assert.equal((await finance.goto(path)).status(),404);
    assert.equal((await finance.goto(path+'/comments')).status(),404);
    await page.goto(path);
    assert.doesNotMatch(await page.content(),/1234567|7654321|12\.3456|rent_cents|tax_rate/);
    assert.match(await page.content(),/Browser lease tag/);
    const reader=await open(readerCookie);
    await reader.goto(path);
    assert.equal(await reader.getByRole('button',{name:'Save Draft details',exact:true}).count(),0);
    assert.equal(await reader.locator('[name=agreement_file_id]').count(),0);
    await reader.goto(path+'/billing');
    assert.equal(await reader.getByRole('button',{name:'Save Billing terms',exact:true}).count(),0);
    assert.match(await reader.content(),/7654321/);
    console.log('persisted base details + four collaborations; independent Billing save/read; base/Billing/reader denials passed');
  } finally { await browser.close(); }
})().catch(err=>{console.error(err);process.exit(1);});
